INSERT INTO "products" ("name", "category", "description", "notes", "size", "price", "image", "in_stock", "featured") VALUES
('Vector IX', 'signature', 'Our flagship signature impression. A commanding, long-lasting trail of fresh spice over a smoky, woody heart — made for those who enter a room and own it.', 'Bergamot · Pink Pepper · Ambroxan · Smoked Woods', '100ml', 4500, '/img/signature.png', true, true),
('Hawas Ice', 'signature', 'An icy, aquatic impression with a sweet fruity twist. Cool, crisp and irresistibly fresh for Karachi summers.', 'Apple · Cinnamon · Plum · Marine Accord · Musk', '100ml', 3800, '/img/ice.png', true, true),
('Office for Men', 'spray', 'Clean, confident and professional. A polished citrus-woody spray that lasts through the longest workday.', 'Lemon · Lavender · Vetiver · White Musk', '100ml', 3200, '/img/spray.png', true, true),
('Royal Oud Attar', 'attar', 'Pure, alcohol-free concentrated oud oil in the classic tradition. A few drops last the entire day.', 'Cambodian Oud · Saffron · Rose · Amber', '12ml', 2800, '/img/attar.png', true, true),
('Musk Tahara Attar', 'attar', 'Soft, powdery and comforting white musk attar — gentle enough for everyday wear.', 'White Musk · Rose Water · Vanilla', '6ml', 1200, '/img/attar.png', true, false),
('Sandal Amber Attar', 'attar', 'Creamy Mysore-style sandalwood wrapped in warm resinous amber.', 'Sandalwood · Amber · Cardamom', '12ml', 2200, '/img/attar.png', true, false),
('Midnight Velvet', 'spray', 'A seductive evening spray for her — dark florals, vanilla and a whisper of oud.', 'Blackcurrant · Rose · Vanilla · Oud', '100ml', 3600, '/img/spray.png', true, false),
('Citrus Noir', 'spray', 'Bright Italian citrus with a mysterious dark-woods finish. Unisex and effortless.', 'Grapefruit · Neroli · Cedar · Patchouli', '50ml', 2400, '/img/spray.png', true, false),
('Oud Booster Blend', 'booster', 'Layer it with any perfume to add depth, projection and a rich oud signature.', 'Oud · Leather · Smoky Resins', '30ml', 1800, '/img/booster.png', true, true),
('Amber Glow Booster', 'booster', 'A honeyed amber booster that makes any fragrance warmer and longer lasting.', 'Amber · Honey · Tonka', '30ml', 1600, '/img/booster.png', true, false),
('Fresh Blast Booster', 'booster', 'A citrus-aquatic booster that lifts and freshens your favourite scent.', 'Lime · Mint · Sea Salt', '30ml', 1500, '/img/booster.png', false, false),
('Sultan Impression', 'signature', 'A regal impression of a legendary Arabian classic — sweet, smoky and unforgettable.', 'Saffron · Jasmine · Amberwood · Fir Resin', '100ml', 4200, '/img/signature.png', true, false);
